from __future__ import annotations
import heapq
from itertools import count


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, bool] = {}
        self._tickets: dict[int, dict] = {}
        self._ticket_id_counter = count(1)
        self._heap: list[tuple] = []
        self._priority_map = {name: idx for idx, name in enumerate(self.PRIORITIES)}

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        """Open a ticket; returns its id."""
        if not title:
            raise ValueError("Ticket title cannot be empty.")
        if priority not in self._priority_map:
            raise ValueError(f"Invalid priority: {priority}")

        ticket_id = next(self._ticket_id_counter)
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "open",
        }
        self._push_to_queue(ticket_id)
        return ticket_id

    def _push_to_queue(self, ticket_id: int) -> None:
        ticket = self._tickets[ticket_id]
        customer = ticket["customer"]
        is_vip = self._customers.get(customer, False)
        vip_score = 0 if is_vip else 1
        prio_score = -self._priority_map[ticket["priority"]]

        # Priority order:
        # 1. VIP customers (vip_score: 0 for VIP, 1 for non-VIP)
        # 2. Priority level (prio_score: -2 for critical, -1 for high, 0 for normal)
        # 3. Order opened (ticket_id: FIFO)
        heapq.heappush(self._heap, (vip_score, prio_score, ticket_id))

    def next_ticket(self) -> int | None:
        """Take the ticket that should be handled next out of the queue; None if the queue is empty."""
        while self._heap:
            _, _, ticket_id = heapq.heappop(self._heap)
            ticket = self._tickets.get(ticket_id)
            if ticket and ticket["status"] == "open":
                ticket["status"] = "in_progress"
                return ticket_id
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id in self._tickets:
            self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        """Put a ticket back into the queue."""
        if ticket_id not in self._tickets:
            raise KeyError(f"Ticket {ticket_id} does not exist.")

        ticket = self._tickets[ticket_id]
        if ticket["status"] != "open":
            ticket["status"] = "open"
            self._push_to_queue(ticket_id)
```

